-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

hl.on("hyprland.start", function()
    -- NOTE: the two lines below were in the previous hyprland.lua but not in
    -- hyprland.conf.old; kept in case you rely on them. Remove if unwanted.
    --hl.exec_cmd("orbit daemon")
    -- hl.exec_cmd("swaync & waybar")
    hl.exec_cmd("pkill -x xfce4-notifyd; pkill -x dunst; pkill -x mako")
    hl.exec_cmd("qs -c ricegueh")
    hl.exec_cmd("foot --server")
    hl.exec_cmd("hyprlock")
    --hl.exec_cmd("udiskie &")
    --hl.exec_cmd("/usr/lib/xfce4/notifyd/xfce4-notifyd")
    --hl.exec_cmd("nm-applet")
    --hl.exec_cmd("/usr/bin/kdeconnectd")
    --hl.exec_cmd("xfce4-panel & awww-daemon")
    --hl.exec_cmd("awww img /home/notfuad/Pictures/Hydrochoeris_hydrochaeris_in_Brazil_in_Petrópolis,_Rio_de_Janeiro,_Brazil_09.jpg")
    --hl.exec_cmd("swaybg")
    hl.exec_cmd("/usr/lib/xdg-desktop-portal-hyprland")
    hl.exec_cmd("/usr/lib/hyprpolkitagent/hyprpolkitagent")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("hypridle")
