    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("hyprpm reload")
    --hl.exec_cmd("/home/notfuad/.venv/bin/python /home/notfuad/Documents/kodingpribadi/oledcoloki2cpc/dashboard.py")
    hl.exec_cmd("xhost +si:localuser:root")
    hl.exec_cmd("flameshot")
end)

